import { useEffect, useMemo, useRef, useState, type ChangeEvent, type ReactNode, type RefObject } from "react";
import { AlertTriangle, CloudOff, Download, Eye, FileCheck2, FolderKanban, Mail, MapPin, MessageCircle, Plus, RefreshCw, Save, ShieldCheck, SlidersHorizontal, Upload, UploadCloud, UserCog, Wifi } from "lucide-react";
import DashboardLayout from "@/components/DashboardLayout";
import { TerritorialFieldMap, TerritorialFieldTestGuide, TerritorialPermissionPanel } from "@/components/TerritorialFieldTools";
import { TerritorialManuals } from "@/components/TerritorialManuals";
import { TerritorialPilotConsole } from "@/components/TerritorialPilotConsole";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { MAPPER_ROLES, WORLD_OBJECT_STATUSES, WORLD_OBJECT_TYPES, calculateConfidenceBreakdown, type MapperRole } from "../../../shared/territorialTrust";

const statusTone: Record<string, string> = {
  CAPTURED: "border-cyan-200/30 bg-cyan-200/10 text-cyan-100",
  UNDER_REVIEW: "border-amber-200/30 bg-amber-200/10 text-amber-100",
  EVIDENCE_REQUIRED: "border-orange-200/30 bg-orange-200/10 text-orange-100",
  VERIFIED: "border-emerald-200/30 bg-emerald-200/10 text-emerald-100",
  PUBLISHED: "border-green-200/30 bg-green-200/10 text-green-100",
  DISPUTED: "border-rose-200/30 bg-rose-200/10 text-rose-100",
  REJECTED: "border-red-200/30 bg-red-200/10 text-red-100",
  ARCHIVED: "border-slate-200/20 bg-slate-200/10 text-slate-300",
};

const emptySessionId = `TSES-${"0".repeat(24)}`;
const emptyObjectId = `WOBJ-${"0".repeat(24)}`;
const FILTERS_KEY = "milukita-territorial-filter-presets-v1";

type FilterSnapshot = { search: string; status: string; objectType: string; evidenceFilter: string; sort: string };
type FilterPreset = FilterSnapshot & { id: string; name: string; savedAt: string };
type SyncNotice = { id: string; text: string; tone: "success" | "warning" | "error"; createdAt: string };
type OfflineQueueItem = { localId: string; payload: Record<string, unknown>; status: "LOCAL_PENDING" | "SYNCING" | "SYNCED" | "CONFLICT" | "SYNC_ERROR" | "OFFLINE" | "PENDING_SYNC"; createdAt: string; error?: string; serverPublicId?: string; conflictJson?: string };
type ConflictResolution = "KEEP_LOCAL" | "KEEP_REMOTE" | "MERGE" | "MARK_DISPUTED";
type DraftObject = { objectType: string; name: string; description: string; latitude: string; longitude: string; accuracyMeters: number; geometry: Record<string, unknown>; captureSessionPublicId?: string };

function loadFilterPresets(): FilterPreset[] {
  try {
    const raw = window.localStorage.getItem(FILTERS_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter(item => item && typeof item.name === "string") : [];
  } catch {
    return [];
  }
}

function persistFilterPresets(presets: FilterPreset[]) {
  window.localStorage.setItem(FILTERS_KEY, JSON.stringify(presets.slice(0, 12)));
}

function parseConflict(item: OfflineQueueItem) {
  if (!item.conflictJson) return null;
  try {
    const parsed = JSON.parse(item.conflictJson) as { local?: { worldObject?: Record<string, unknown>; baseVersion?: number; capturedAt?: string }; server?: Record<string, unknown> };
    return parsed.local || parsed.server ? parsed : null;
  } catch {
    return null;
  }
}

export default function TerritorialTrustPage({ surface = "admin" }: { surface?: "admin" | "mapper" | "the-eye" }) {
  const fieldMode = surface !== "admin";
  const fieldIsMapper = surface === "mapper";
  const [status, setStatus] = useState<(typeof WORLD_OBJECT_STATUSES)[number] | "ALL">("ALL");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [showAuditReport, setShowAuditReport] = useState(false);
  const [showSessionCreate, setShowSessionCreate] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [objectType, setObjectType] = useState("ALL");
  const [evidenceFilter, setEvidenceFilter] = useState<"ALL" | "WITH_EVIDENCE" | "WITHOUT_EVIDENCE">("ALL");
  const [sort, setSort] = useState<"updated" | "name" | "status">("updated");
  const [filterPresets, setFilterPresets] = useState<FilterPreset[]>(loadFilterPresets);
  const [presetName, setPresetName] = useState("");
  const [importProgress, setImportProgress] = useState(0);
  const [isOnline, setIsOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);
  const [offlineQueue, setOfflineQueue] = useState<OfflineQueueItem[]>(() => { try { const raw = window.localStorage.getItem("milukita-offline-captures-v1"); const parsed = raw ? JSON.parse(raw) : []; return Array.isArray(parsed) ? parsed : []; } catch { return []; } });
  const [syncingOffline, setSyncingOffline] = useState(false);
  const [showSyncDrawer, setShowSyncDrawer] = useState(false);
  const [syncNotifications, setSyncNotifications] = useState<SyncNotice[]>([]);
  const [syncHistory, setSyncHistory] = useState<SyncNotice[]>(() => { try { const raw = window.localStorage.getItem("milukita-sync-history-v1"); const parsed = raw ? JSON.parse(raw) : []; return Array.isArray(parsed) ? parsed.slice(0, 30) : []; } catch { return []; } });
  const importRef = useRef<HTMLInputElement>(null);

  const list = trpc.territorial.list.useQuery(status === "ALL" ? undefined : { status });
  const detail = trpc.territorial.detail.useQuery({ publicId: selectedId ?? emptyObjectId }, { enabled: Boolean(selectedId) });
  const snapshots = trpc.territorial.snapshots.useQuery({ objectPublicId: selectedId ?? emptyObjectId }, { enabled: Boolean(selectedId) });
  const reviewQueue = trpc.territorial.reviewQueue.useQuery(surface === "the-eye" ? { status: ["CAPTURED", "UNDER_REVIEW", "EVIDENCE_REQUIRED", "DISPUTED"] } : undefined, { enabled: surface === "the-eye" });
  const [eyeFilter, setEyeFilter] = useState("");
  const captureSessions = trpc.territorial.captureSessions.useQuery();
  const sessionDetail = trpc.territorial.captureSessionDetail.useQuery({ publicId: selectedSessionId ?? emptySessionId }, { enabled: Boolean(selectedSessionId) });
  const utils = trpc.useUtils();

  const create = trpc.territorial.create.useMutation({
    onSuccess: created => { setSelectedId(created?.publicId ?? null); setShowCreate(false); setNotice("Objeto capturado; todavía no está verificado ni publicado."); void utils.territorial.list.invalidate(); void utils.territorial.captureSessions.invalidate(); },
    onError: error => setNotice(error.message),
  });
  const queueOffline = trpc.territorial.queueOfflineCapture.useMutation();
  const syncOffline = trpc.territorial.syncOfflineCapture.useMutation();
  const resolveConflict = trpc.territorial.resolveOfflineConflict.useMutation();
  const restoreSnapshot = trpc.territorial.restoreSnapshot.useMutation({ onSuccess: restored => { setSelectedId(restored?.publicId ?? selectedId); setNotice("Snapshot restaurado como nueva versión CAPTURED; debe pasar nuevamente por The Eye."); void utils.territorial.detail.invalidate(); void snapshots.refetch(); }, onError: error => setNotice(error.message) });
  const updateObject = trpc.territorial.updateObject.useMutation({
    onSuccess: updated => { setNotice("Cambios guardados como nueva versión CAPTURED; requiere volver a pasar por The Eye."); setSelectedId(updated?.publicId ?? selectedId); void utils.territorial.list.invalidate(); void utils.territorial.detail.invalidate(); void utils.territorial.captureSessionDetail.invalidate(); },
    onError: error => setNotice(error.message),
  });
  const addClaim = trpc.territorial.addClaim.useMutation({ onSuccess: () => { setNotice("Afirmación registrada como no verificada."); void utils.territorial.detail.invalidate(); }, onError: error => setNotice(error.message) });
  const addSource = trpc.territorial.addSource.useMutation({ onSuccess: () => { setNotice("Fuente registrada."); void utils.territorial.detail.invalidate(); }, onError: error => setNotice(error.message) });
  const addEvidence = trpc.territorial.addEvidence.useMutation({ onSuccess: () => { setNotice("Evidencia registrada con su huella de integridad."); void utils.territorial.detail.invalidate(); }, onError: error => setNotice(error.message) });
  const review = trpc.territorial.review.useMutation({ onSuccess: () => { setNotice("Decisión de The Eye registrada; revisa el estado antes de publicar."); void utils.territorial.list.invalidate(); void utils.territorial.detail.invalidate(); void reviewQueue.refetch(); }, onError: error => setNotice(error.message) });
  const publish = trpc.territorial.publish.useMutation({ onSuccess: () => { setNotice("Versión publicada por Human Authority."); void utils.territorial.list.invalidate(); void utils.territorial.detail.invalidate(); }, onError: error => setNotice(error.message) });
  const myRole = trpc.territorial.myRole.useQuery();
  const roles = trpc.territorial.roles.useQuery();
  const assignRole = trpc.territorial.assignRole.useMutation({ onSuccess: () => { setNotice("Rol territorial actualizado."); void roles.refetch(); void myRole.refetch(); }, onError: error => setNotice(error.message) });
  const createSession = trpc.territorial.createCaptureSession.useMutation({ onSuccess: session => { const nextId = session?.publicId ?? null; setSelectedSessionId(nextId); setShowSessionCreate(false); setNotice("CaptureSession creada. Las siguientes capturas pueden quedar agrupadas en ella."); void captureSessions.refetch(); }, onError: error => setNotice(error.message) });
  const importData = trpc.territorial.importData.useMutation({ onSuccess: result => { setImportProgress(100); setNotice(`Importación completada: ${result.imported} registros; ${result.rejected} rechazados.`); void utils.territorial.list.invalidate(); void utils.territorial.captureSessions.invalidate(); void sessionDetail.refetch(); }, onError: error => { setImportProgress(0); setNotice(error.message); } });
  const exportData = trpc.territorial.exportData.useMutation();
  const uploadAsset = trpc.territorial.uploadAsset.useMutation({ onSuccess: () => { setNotice("Asset subido a S3 y asociado al WorldObject."); void utils.territorial.detail.invalidate(); }, onError: error => setNotice(error.message) });

  useEffect(() => {
    const goOnline = () => setIsOnline(true);
    const goOffline = () => setIsOnline(false);
    window.addEventListener("online", goOnline); window.addEventListener("offline", goOffline);
    return () => { window.removeEventListener("online", goOnline); window.removeEventListener("offline", goOffline); };
  }, []);
  useEffect(() => { window.localStorage.setItem("milukita-offline-captures-v1", JSON.stringify(offlineQueue)); }, [offlineQueue]);
  useEffect(() => { window.localStorage.setItem("milukita-sync-history-v1", JSON.stringify(syncHistory.slice(0, 30))); }, [syncHistory]);
  useEffect(() => {
    if (!importData.isPending) return;
    setImportProgress(12);
    const timer = window.setInterval(() => setImportProgress(value => Math.min(value + 9, 88)), 360);
    return () => window.clearInterval(timer);
  }, [importData.isPending]);

  const selectedSessionDbId = selectedSessionId ? captureSessions.data?.find(session => session.publicId === selectedSessionId)?.id : undefined;
  const filteredObjects = useMemo(() => {
    const normalized = search.trim().toLowerCase();
    const rows = (list.data ?? []).filter(item => {
      const matchesSearch = !normalized || `${item.publicId} ${item.name} ${item.description} ${item.objectType}`.toLowerCase().includes(normalized);
      const matchesSession = !selectedSessionId || item.captureSessionId === selectedSessionDbId;
      const matchesType = objectType === "ALL" || item.objectType === objectType;
      const hasEvidence = Array.isArray(item.assets) && item.assets.length > 0;
      const matchesEvidence = evidenceFilter === "ALL" || (evidenceFilter === "WITH_EVIDENCE" ? hasEvidence : !hasEvidence);
      return matchesSearch && matchesSession && matchesType && matchesEvidence;
    });
    return rows.sort((a, b) => sort === "name" ? a.name.localeCompare(b.name) : sort === "status" ? a.status.localeCompare(b.status) : new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
  }, [list.data, search, selectedSessionId, selectedSessionDbId, objectType, evidenceFilter, sort]);

  const currentFilters: FilterSnapshot = { search, status, objectType, evidenceFilter, sort };
  const handleCreate = (value: DraftObject) => {
    if (isOnline) { create.mutate(value); return; }
    const localId = `local-${crypto.randomUUID()}`;
    setOfflineQueue(current => [{ localId, payload: { clientCaptureId: localId, deviceFingerprint: `${navigator.userAgent.slice(0, 80)}-${window.screen.width}x${window.screen.height}`, capturedAt: new Date().toISOString(), worldObject: value }, status: "OFFLINE", createdAt: new Date().toISOString() }, ...current]);
    setShowCreate(false);
    setNotice("Captura guardada localmente como OFFLINE. Usa Sincronizar cuando vuelva la conexión.");
  };
  const notifySync = (text: string, tone: "success" | "warning" | "error") => { const notice = { id: crypto.randomUUID(), text, tone, createdAt: new Date().toISOString() }; setSyncNotifications(current => [notice, ...current].slice(0, 8)); setSyncHistory(current => [notice, ...current].slice(0, 30)); };
  const auditSummary = "MAPA DE REALIDAD DEL SISTEMA\\n\\nImplementado: Territorial Trust CAPTURE → VERIFY → PUBLISH; Mapper y The Eye; CaptureSession; cola offline; conflictos manuales; OpenStreetMap; evidencias S3; exportaciones; Field Gate y diagnóstico de permisos.\\n\\nSimulado o condicionado: WebXR depende del navegador/dispositivo; Cast/DLNA y TV no están integrados; QR productivos dependen de una URL pública; GPS, cámara, micrófono, escaneo QR y offline requieren validación física.\\n\\nGobernanza: publicación únicamente mediante Human Authority. MJP CORE (RNG, Wallet, Rules, ledger, settlement y resultados) permanece aislado y sin cambios en esta orden.\\n\\nEstado: CODE_READY_FOR_PUBLISH; PUBLIC_DEPLOYMENT_NOT_EXECUTED; DOMAIN_NOT_CONFIGURED; PHYSICAL_FIELD_GATE_PENDING.";
  const downloadAuditSummary = () => { const url = URL.createObjectURL(new Blob([auditSummary], { type: "text/plain;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "milukita-mapa-realidad-auditoria.txt"; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(url), 500); };
  const shareAuditSummary = (channel: "email" | "whatsapp") => { const subject = encodeURIComponent("Mapa de realidad de MiLukita"); const body = encodeURIComponent(`${auditSummary}\n\nInforme descargable: ${window.location.origin}/docs/ORDEN_48_MAPA_REALIDAD_AUDITORIA.md`); window.location.href = channel === "email" ? `mailto:?subject=${subject}&body=${body}` : `https://wa.me/?text=${encodeURIComponent(`Mapa de realidad de MiLukita\n${window.location.origin}/docs/ORDEN_48_MAPA_REALIDAD_AUDITORIA.md`)}`; };

  const resolveQueuedConflict = async (item: OfflineQueueItem, resolution: ConflictResolution) => {
    if (!item.serverPublicId) { setNotice("Este conflicto todavía no tiene referencia server-side."); return; }
    try {
      const result = await resolveConflict.mutateAsync({ publicId: item.serverPublicId, resolution });
      setOfflineQueue(current => current.map(candidate => candidate.localId === item.localId ? { ...candidate, status: "SYNCED", conflictJson: JSON.stringify(result) } : candidate));
      const label = resolution === "KEEP_LOCAL" ? "versión local" : resolution === "KEEP_REMOTE" ? "versión remota" : resolution === "MERGE" ? "versión combinada" : "objeto marcado DISPUTED";
      setNotice(`Conflicto resuelto: se conservó ${label}.`); notifySync(`Conflicto ${item.localId.slice(-8)} resuelto mediante ${resolution}.`, resolution === "MARK_DISPUTED" ? "warning" : "success");
      void utils.territorial.list.invalidate(); void utils.territorial.detail.invalidate();
    } catch (error) { const text = error instanceof Error ? error.message : "CONFLICT_RESOLUTION_FAILED"; setNotice(text); notifySync(text, "error"); }
  };
  const manualSync = async () => {
    if (!isOnline) { setNotice("No hay conexión. La cola offline permanece guardada localmente."); return; }
    const pending = offlineQueue.filter(item => item.status === "OFFLINE" || item.status === "LOCAL_PENDING" || item.status === "PENDING_SYNC" || item.status === "SYNC_ERROR");
    if (!pending.length) { setNotice("No hay capturas pendientes de sincronización."); return; }
    setSyncingOffline(true);
    let synced = 0;
    try {
      for (const item of pending) {
        setOfflineQueue(current => current.map(candidate => candidate.localId === item.localId ? { ...candidate, status: "SYNCING" } : candidate));
        try {
          const queued = await queueOffline.mutateAsync({ payload: item.payload as never });
          const serverResult = await syncOffline.mutateAsync({ publicId: queued.publicId });
          const nextStatus = serverResult.status === "CONFLICT" ? "CONFLICT" : "SYNCED";
          setOfflineQueue(current => current.map(candidate => candidate.localId === item.localId ? { ...candidate, status: nextStatus, serverPublicId: queued.publicId, conflictJson: serverResult.conflictJson } : candidate));
          if (nextStatus === "CONFLICT") { notifySync(`Conflicto detectado en ${item.localId.slice(-8)}. Requiere decisión humana.`, "warning"); } else { synced += 1; notifySync(`Captura ${item.localId.slice(-8)} sincronizada correctamente.`, "success"); }
        } catch (error) {
          const errorText = error instanceof Error ? error.message : "SYNC_ERROR";
          setOfflineQueue(current => current.map(candidate => candidate.localId === item.localId ? { ...candidate, status: "SYNC_ERROR", error: errorText } : candidate));
          notifySync(`Error en ${item.localId.slice(-8)}: ${errorText}. Puedes reintentar.`, "error");
        }
      }
      setNotice(`Sincronización manual completada: ${synced}/${pending.length} capturas recibidas.`); notifySync(`Sincronización completada: ${synced}/${pending.length} elementos recibidos.`, synced === pending.length ? "success" : "warning");
      void utils.territorial.list.invalidate(); void captureSessions.refetch();
    } catch (error) {
      setNotice(error instanceof Error ? error.message : "SYNC_FAILED");
    } finally { setSyncingOffline(false); }
  };
  const saveCurrentPreset = () => {
    const name = presetName.trim();
    if (!name) return;
    const next = [{ ...currentFilters, id: crypto.randomUUID(), name, savedAt: new Date().toISOString() }, ...filterPresets.filter(item => item.name.toLowerCase() !== name.toLowerCase())];
    setFilterPresets(next);
    persistFilterPresets(next);
    setPresetName("");
    setNotice(`Filtro favorito “${name}” guardado en este navegador.`);
  };
  const applyPreset = (preset: FilterPreset) => { setSearch(preset.search); setStatus(preset.status as typeof status); setObjectType(preset.objectType); setEvidenceFilter(preset.evidenceFilter as typeof evidenceFilter); setSort(preset.sort as typeof sort); setNotice(`Filtro favorito “${preset.name}” aplicado.`); };
  const deletePreset = (id: string) => { const next = filterPresets.filter(item => item.id !== id); setFilterPresets(next); persistFilterPresets(next); };
  const downloadExport = async (format: "csv" | "geojson") => { const result = await exportData.mutateAsync({ format, status: status === "ALL" ? undefined : status }); const blob = new Blob([result.content], { type: result.contentType }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = result.filename; anchor.click(); URL.revokeObjectURL(url); setNotice(`Exportación ${format.toUpperCase()} descargada.`); };

  const pageContent = <main className="min-h-screen bg-[#06120e] px-4 py-5 text-slate-100 sm:px-8 sm:py-8" data-territorial-surface={surface}><div className="mx-auto max-w-7xl"><header className="flex flex-col justify-between gap-5 border-b border-white/10 pb-6 lg:flex-row lg:items-end"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-cyan-200">{fieldMode ? `MiLukita · ${fieldIsMapper ? "Mapper" : "The Eye"} · Field Gate 001` : "Territorial Trust Layer · Restricted Admin"}</p><h1 className="mt-2 font-display text-4xl text-white sm:text-5xl">{fieldMode ? (fieldIsMapper ? "Captura el territorio." : "Revisa la evidencia.") : "MiLukita Mapper + The Eye"}</h1><p className="mt-3 max-w-3xl text-sm leading-6 text-slate-300">{fieldMode ? (fieldIsMapper ? "Registra un punto, su ubicación y evidencia. Nada se publica desde este dispositivo." : "Contrasta Claims, Sources y Evidence antes de solicitar aprobación humana.") : "Mapper captura la realidad y su evidencia. The Eye contrasta y recomienda. Solo Human Authority puede publicar una versión apta para el Runtime."}</p></div><div className="flex flex-wrap gap-2">{fieldIsMapper ? <Button onClick={() => setShowCreate(value => !value)} className="bg-cyan-200 text-[#062019] hover:bg-cyan-100"><Plus className="mr-2 h-4 w-4" />Nueva captura</Button> : null}{!fieldMode ? <Button type="button" variant="outline" onClick={() => setShowAuditReport(true)} className="border-emerald-200/30 text-emerald-100"><FileCheck2 className="mr-2 h-4 w-4" />Informe de auditoría</Button> : null}<Badge className="border border-rose-200/20 bg-rose-200/10 px-3 py-2 text-rose-100"><ShieldCheck className="mr-2 h-4 w-4" />MJP CORE protegido</Badge></div></header>

  {notice ? <div className="mt-5 border border-amber-200/20 bg-amber-200/10 p-4 text-sm text-amber-50" role="status">{notice}<button type="button" className="ml-3 text-amber-200 underline" onClick={() => setNotice(null)}>Cerrar</button></div> : null}
  {surface === "the-eye" ? <ReviewQueuePanel items={(reviewQueue.data ?? []).filter(item => !eyeFilter.trim() || `${item.publicId} ${item.name} ${item.objectType} ${item.status}`.toLowerCase().includes(eyeFilter.trim().toLowerCase()))} loading={reviewQueue.isLoading} filter={eyeFilter} onFilter={setEyeFilter} selectedId={selectedId} onSelect={id => { setSelectedId(id); setSelectedSessionId(null); }} /> : null}
  {(fieldIsMapper || !fieldMode) ? <NetworkStatusPanel isOnline={isOnline} offlineQueue={offlineQueue} syncingOffline={syncingOffline} onSync={manualSync} onOpenQueue={() => setShowSyncDrawer(true)} syncNotifications={syncNotifications} syncHistory={syncHistory} /> : null}
  {showSyncDrawer ? <aside className="fixed inset-y-0 right-0 z-50 w-full max-w-md border-l border-cyan-200/20 bg-[#071914] p-6 text-slate-100 shadow-2xl" aria-label="Progreso de cola offline"><div className="flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-cyan-200">Sincronización offline</p><h2 className="mt-1 font-display text-2xl text-white">Cola y conflictos</h2></div><Button variant="ghost" onClick={() => setShowSyncDrawer(false)} className="text-slate-300">Cerrar</Button></div><div className="mt-5 border border-white/10 bg-black/20 p-4"><div className="flex justify-between text-xs text-slate-400"><span>Progreso</span><strong className="text-white">{offlineQueue.filter(item => item.status === "SYNCED").length}/{offlineQueue.length || 0}</strong></div><div className="mt-2 h-2 bg-white/10"><div className="h-2 bg-cyan-200 transition-all" style={{ width: `${offlineQueue.length ? Math.round(offlineQueue.filter(item => item.status === "SYNCED").length / offlineQueue.length * 100) : 0}%` }} /></div></div><div className="mt-5 space-y-3">{offlineQueue.length ? offlineQueue.map(item => <div key={item.localId} className="border border-white/10 bg-black/20 p-4"><div className="flex items-center justify-between gap-3"><span className="font-mono text-xs text-slate-400">{item.localId.slice(-16)}</span><Badge className={item.status === "SYNCED" ? "border-emerald-200/30 bg-emerald-200/10 text-emerald-100" : item.status === "CONFLICT" ? "border-orange-200/30 bg-orange-200/10 text-orange-100" : item.status === "SYNC_ERROR" ? "border-rose-200/30 bg-rose-200/10 text-rose-100" : item.status === "SYNCING" ? "border-violet-200/30 bg-violet-200/10 text-violet-100" : "border-cyan-200/30 bg-cyan-200/10 text-cyan-100"}>{item.status}</Badge></div>{item.status === "CONFLICT" ? <div className="mt-3 space-y-3"><p className="text-xs leading-5 text-orange-100">La versión local y remota divergen. Elige una resolución; ninguna opción elimina el historial de auditoría.</p>{(() => { const conflict = parseConflict(item); const local = conflict?.local?.worldObject ?? {}; const remote = conflict?.server ?? {}; const fields = ["name", "objectType", "description", "latitude", "longitude", "version", "status"]; return <details open className="border border-orange-200/15 bg-orange-200/[.04] p-3"><summary className="cursor-pointer text-xs font-bold uppercase tracking-[.12em] text-orange-100">Comparar versión A / versión B</summary><div className="mt-3 grid gap-3 md:grid-cols-2"><div><p className="text-xs font-bold text-cyan-200">A · local · base v{String(conflict?.local?.baseVersion ?? "—")}</p>{fields.map(field => <p key={`local-${field}`} className="mt-2 text-xs text-slate-300"><span className="text-slate-500">{field}: </span>{String(local[field] ?? "—")}</p>)}</div><div><p className="text-xs font-bold text-amber-200">B · remota · v{String(remote.version ?? "—")}</p>{fields.map(field => <p key={`remote-${field}`} className="mt-2 text-xs text-slate-300"><span className="text-slate-500">{field}: </span>{String(remote[field] ?? "—")}</p>)}</div></div></details>; })()}<div className="grid grid-cols-2 gap-2"><Button size="sm" onClick={() => resolveQueuedConflict(item, "KEEP_LOCAL")} disabled={resolveConflict.isPending} className="bg-cyan-200 text-[#062019]">Aceptar A</Button><Button size="sm" onClick={() => resolveQueuedConflict(item, "KEEP_REMOTE")} disabled={resolveConflict.isPending} variant="outline" className="border-white/20 text-white">Aceptar B</Button><Button size="sm" onClick={() => resolveQueuedConflict(item, "MERGE")} disabled={resolveConflict.isPending} variant="outline" className="border-violet-200/30 text-violet-100">Combinar</Button><Button size="sm" onClick={() => resolveQueuedConflict(item, "MARK_DISPUTED")} disabled={resolveConflict.isPending} variant="outline" className="border-rose-200/30 text-rose-100">Marcar disputa</Button></div><p className="text-[11px] text-slate-500">Para solicitar evidencia o escalar, marca el objeto como disputa y continúa la revisión en The Eye/Human Authority.</p></div> : item.status === "SYNC_ERROR" ? <div className="mt-2"><p className="text-xs text-rose-100">{item.error ?? "La sincronización falló."}</p><p className="mt-1 text-xs text-slate-500">La captura se conserva localmente y puede reintentarse.</p></div> : <p className="mt-2 text-xs text-slate-500">{item.status === "SYNCED" ? "Recibido por el servidor." : item.status === "SYNCING" ? "Enviando de forma secuencial…" : "Esperando próxima sincronización manual."}</p>}</div>) : <p className="text-sm text-slate-500">La cola está vacía.</p>}</div></aside> : null}

{!fieldMode ? <section className="mt-7 grid gap-4 md:grid-cols-3"><div className="border border-cyan-200/15 bg-cyan-200/[.04] p-5"><MapPin className="h-5 w-5 text-cyan-200" /><p className="mt-4 text-xs font-bold uppercase tracking-[.14em] text-cyan-200">CAPTURA</p><p className="mt-2 text-sm leading-6 text-slate-300">Registra ubicación, precisión, descripción y evidencia de campo.</p></div><div className="border border-amber-200/15 bg-amber-200/[.04] p-5"><Eye className="h-5 w-5 text-amber-200" /><p className="mt-4 text-xs font-bold uppercase tracking-[.14em] text-amber-200">VERIFICACIÓN</p><p className="mt-2 text-sm leading-6 text-slate-300">Contrasta fuentes, claims, actualidad, duplicados y contradicciones.</p></div><div className="border border-emerald-200/15 bg-emerald-200/[.04] p-5"><FileCheck2 className="h-5 w-5 text-emerald-200" /><p className="mt-4 text-xs font-bold uppercase tracking-[.14em] text-emerald-200">PUBLICACIÓN</p><p className="mt-2 text-sm leading-6 text-slate-300">Solo una versión verificada, con fuente y evidencia, puede publicarse.</p></div></section> : null}

{showCreate ? <CreateObjectForm submitting={create.isPending} sessionPublicId={selectedSessionId ?? undefined} onCancel={() => setShowCreate(false)} onSubmit={handleCreate} /> : null}
{showAuditReport ? <div className="fixed inset-0 z-50 grid place-items-center bg-black/75 p-4 backdrop-blur-sm" role="presentation" onMouseDown={() => setShowAuditReport(false)}><section role="dialog" aria-modal="true" aria-labelledby="audit-summary-title" className="max-h-[85vh] w-full max-w-3xl overflow-y-auto border border-emerald-200/30 bg-[#071a12] p-6 shadow-2xl" onMouseDown={event => event.stopPropagation()}><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-emerald-200">Auditoría constitucional</p><h2 id="audit-summary-title" className="mt-2 font-display text-3xl text-white">Mapa de realidad del sistema</h2></div><Button type="button" variant="outline" onClick={() => setShowAuditReport(false)} className="border-white/15 text-white">Cerrar</Button></div><pre className="mt-5 whitespace-pre-wrap border border-white/10 bg-black/20 p-4 text-sm leading-6 text-slate-200">{auditSummary}</pre><div className="mt-5 flex flex-wrap justify-end gap-2"><Button type="button" variant="outline" onClick={() => shareAuditSummary("email")} className="border-white/15 text-white"><Mail className="mr-2 h-4 w-4" />Correo</Button><Button type="button" variant="outline" onClick={() => shareAuditSummary("whatsapp")} className="border-emerald-200/30 text-emerald-100"><MessageCircle className="mr-2 h-4 w-4" />WhatsApp</Button><Button type="button" onClick={downloadAuditSummary} className="bg-emerald-200 text-[#062019] hover:bg-emerald-100"><Download className="mr-2 h-4 w-4" />Descargar resumen TXT</Button></div></section></div> : null}
{showSessionCreate ? <CreateSessionForm submitting={createSession.isPending} onCancel={() => setShowSessionCreate(false)} onSubmit={value => createSession.mutate(value)} /> : null}
  {(fieldIsMapper || !fieldMode) ? <CaptureSessionPanel sessions={captureSessions.data ?? []} selectedId={selectedSessionId} creating={createSession.isPending} onSelect={id => { setSelectedSessionId(id); setSelectedId(null); }} onCreate={() => setShowSessionCreate(true)} /> : null}
{!fieldMode ? <>
<OperationsPanel exporting={exportData.isPending} importing={importData.isPending} progress={importProgress} importRef={importRef} sessionPublicId={selectedSessionId ?? undefined} onExport={downloadExport} onImport={(format, content, sessionPublicId) => importData.mutate({ format, content, captureSessionPublicId: sessionPublicId })} />
<RolePanel myRole={myRole.data} roles={roles.data ?? []} assigning={assignRole.isPending} onAssign={(userId, role) => assignRole.mutate({ userId, role })} />
<TerritorialPilotConsole onNotice={setNotice} />
</> : null}

<section className="mt-7 grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><div className="border border-white/10 bg-white/[.03] p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-400">Mapper registry</p><h2 className="mt-1 font-display text-3xl text-white">Objetos territoriales</h2><p className="mt-1 text-xs text-slate-500">{filteredObjects.length} visibles · {selectedSessionId ? `sesión ${selectedSessionId}` : "todas las sesiones"}</p></div><div className="flex flex-wrap gap-2"><Input aria-label="Buscar WorldObjects" value={search} onChange={event => setSearch(event.target.value)} placeholder="Buscar nombre, ID o tipo" className="w-48" /><select aria-label="Filtrar WorldObjects por estado" value={status} onChange={event => setStatus(event.target.value as typeof status)} className="border border-white/10 bg-black/20 px-3 py-2 text-xs text-white"><option value="ALL">Todos los estados</option>{WORLD_OBJECT_STATUSES.map(item => <option key={item} value={item}>{item}</option>)}</select><select aria-label="Filtrar WorldObjects por tipo" value={objectType} onChange={event => setObjectType(event.target.value)} className="border border-white/10 bg-black/20 px-3 py-2 text-xs text-white"><option value="ALL">Todos los tipos</option>{WORLD_OBJECT_TYPES.map(item => <option key={item} value={item}>{item}</option>)}</select><select aria-label="Filtrar por evidencia" value={evidenceFilter} onChange={event => setEvidenceFilter(event.target.value as typeof evidenceFilter)} className="border border-white/10 bg-black/20 px-3 py-2 text-xs text-white"><option value="ALL">Toda evidencia</option><option value="WITH_EVIDENCE">Con evidencia</option><option value="WITHOUT_EVIDENCE">Sin evidencia</option></select><select aria-label="Ordenar WorldObjects" value={sort} onChange={event => setSort(event.target.value as typeof sort)} className="border border-white/10 bg-black/20 px-3 py-2 text-xs text-white"><option value="updated">Más recientes</option><option value="name">Nombre</option><option value="status">Estado</option></select></div></div>
<div className="mt-4 border border-white/10 bg-black/20 p-3"><div className="flex flex-wrap items-center gap-2"><SlidersHorizontal className="h-4 w-4 text-cyan-200" /><span className="text-xs font-bold uppercase tracking-[.12em] text-slate-300">Filtros favoritos</span><Input aria-label="Nombre del filtro favorito" value={presetName} onChange={event => setPresetName(event.target.value)} placeholder="Nombre del preset" className="w-40" /><Button size="sm" disabled={!presetName.trim()} onClick={saveCurrentPreset} variant="outline" className="border-cyan-200/25 text-cyan-100"><Save className="mr-1 h-3.5 w-3.5" />Guardar actual</Button></div>{filterPresets.length ? <div className="mt-3 flex flex-wrap gap-2">{filterPresets.map(preset => <span key={preset.id} className="inline-flex items-center gap-1 border border-white/10 px-2 py-1 text-xs text-slate-300"><button type="button" className="text-cyan-100 hover:underline" onClick={() => applyPreset(preset)}>{preset.name}</button><button type="button" aria-label={`Eliminar filtro ${preset.name}`} className="ml-1 text-slate-500 hover:text-rose-200" onClick={() => deletePreset(preset.id)}>×</button></span>)}</div> : <p className="mt-2 text-xs text-slate-500">Guarda una combinación para reutilizarla en tu próxima sesión.</p>}</div>
<div className="mt-5 space-y-2">{list.isLoading ? <p className="text-sm text-slate-400">Cargando registros…</p> : filteredObjects.length ? filteredObjects.map(item => <button key={item.publicId} type="button" onClick={() => { setSelectedId(item.publicId); setSelectedSessionId(item.captureSessionId ? captureSessions.data?.find(session => session.id === item.captureSessionId)?.publicId ?? selectedSessionId : selectedSessionId); }} className={`w-full border p-4 text-left ${selectedId === item.publicId ? "border-cyan-200/50 bg-cyan-200/10" : "border-white/10 bg-black/20 hover:border-white/25"}`}><div className="flex items-start justify-between gap-3"><div><p className="font-mono text-xs text-cyan-200">{item.publicId}</p><h3 className="mt-1 font-bold text-white">{item.name}</h3><p className="mt-1 text-xs text-slate-400">{item.objectType} · {item.latitude}, {item.longitude} · v{item.version}</p></div><Badge className={statusTone[item.status] ?? "border-white/15 bg-white/5 text-slate-200"}>{item.status}</Badge></div></button>) : <div className="border border-dashed border-white/15 p-6 text-sm leading-6 text-slate-400">No hay registros que coincidan. Crea una captura o limpia los filtros; ningún registro de captura aparece automáticamente en el Runtime.</div>}</div></div>

<div className="border border-white/10 bg-white/[.03] p-5">{detail.data ? <ObjectDetail object={detail.data} snapshots={snapshots.data ?? []} restoring={restoreSnapshot.isPending} updating={updateObject.isPending} reviewPending={review.isPending} publishPending={publish.isPending} onUpdate={value => updateObject.mutate(value)} onRestore={snapshotPublicId => restoreSnapshot.mutate({ snapshotPublicId })} onReview={(decision, reason, evidenceReviewed) => review.mutate({ objectPublicId: detail.data!.publicId, decision, reason, evidenceReviewed })} onPublish={() => publish.mutate({ objectPublicId: detail.data!.publicId })} onAddClaim={value => addClaim.mutate({ objectPublicId: detail.data!.publicId, ...value })} onAddSource={value => addSource.mutate({ objectPublicId: detail.data!.publicId, ...value })} onAddEvidence={value => addEvidence.mutate({ objectPublicId: detail.data!.publicId, ...value })} onUpload={async (file, assetType, accessScope) => { const base64Data = await fileToBase64(file); uploadAsset.mutate({ objectPublicId: detail.data!.publicId, originalName: file.name, mimeType: file.type, base64Data, assetType, accessScope }); }} /> : <div className="grid min-h-[360px] place-items-center text-center"><div><Eye className="mx-auto h-8 w-8 text-amber-200" /><h2 className="mt-4 font-display text-3xl text-white">The Eye</h2><p className="mt-2 max-w-md text-sm leading-6 text-slate-400">Selecciona un WorldObject para revisar su evidencia, claims, fuentes y workflow de publicación.</p></div></div>}</div></section>

  {!fieldMode ? <TerritorialManuals /> : null}
  {fieldIsMapper || !fieldMode ? <><TerritorialPermissionPanel /><TerritorialFieldTestGuide /><TerritorialFieldMap objects={(filteredObjects as Array<{ publicId: string; name: string; latitude: string; longitude: string; status: string; version: number; accuracyMeters: number; claims?: unknown[]; sources?: unknown[]; evidence?: unknown[] }>) ?? []} />
  </> : null}
  {sessionDetail.data ? <section className="mt-6 border border-violet-200/15 bg-violet-200/[.04] p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-violet-200">CaptureSession activa</p><h2 className="mt-1 font-display text-2xl text-white">{sessionDetail.data.name}</h2><p className="mt-1 text-sm text-slate-400">{sessionDetail.data.territory} · {sessionDetail.data.status} · sync {sessionDetail.data.syncStatus}</p></div><Badge className="border border-violet-200/25 bg-violet-200/10 text-violet-100">{sessionDetail.data.objectCount} objetos · {sessionDetail.data.evidenceCount} evidencias</Badge></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><div className="border border-white/10 bg-black/20 p-3"><p className="text-xs text-slate-500">Responsable</p><p className="mt-1 text-sm text-white">Usuario {sessionDetail.data.mapperUserId}</p></div><div className="border border-white/10 bg-black/20 p-3"><p className="text-xs text-slate-500">Inicio</p><p className="mt-1 text-sm text-white">{new Date(sessionDetail.data.startsAt).toLocaleString()}</p></div><div className="border border-white/10 bg-black/20 p-3"><p className="text-xs text-slate-500">Persistencia</p><p className="mt-1 text-sm text-white">Los objetos conservan su propio workflow.</p></div></div></section> : null}
</div></main>;
  return fieldMode ? pageContent : <DashboardLayout>{pageContent}</DashboardLayout>;
}

function CreateSessionForm({ submitting, onCancel, onSubmit }: { submitting: boolean; onCancel: () => void; onSubmit: (value: { name: string; territory: string; area?: Record<string, unknown> }) => void }) {
  const [form, setForm] = useState({ name: "", territory: "", area: "" });
  return <section className="mt-7 border border-violet-200/20 bg-violet-200/[.04] p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-violet-200">MiLukita Mapper · sesión de campo</p><h2 className="mt-1 font-display text-3xl text-white">Crear CaptureSession</h2></div><Button variant="ghost" onClick={onCancel} className="text-slate-300">Cerrar</Button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-300">Nombre de sesión<Input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} placeholder="Trujillo Centro · septiembre 2026" className="mt-2" /></label><label className="text-xs text-slate-300">Territorio<Input value={form.territory} onChange={event => setForm({ ...form, territory: event.target.value })} placeholder="Centro Histórico de Trujillo" className="mt-2" /></label><label className="text-xs text-slate-300 md:col-span-2">Área o notas JSON opcionales<Textarea value={form.area} onChange={event => setForm({ ...form, area: event.target.value })} placeholder='{"radiusMeters": 500}' className="mt-2" /></label></div><Button disabled={submitting || form.name.trim().length < 2 || form.territory.trim().length < 2} onClick={() => { let area: Record<string, unknown> | undefined; try { area = form.area.trim() ? JSON.parse(form.area) : undefined; } catch { return; } onSubmit({ name: form.name, territory: form.territory, area }); }} className="mt-5 bg-violet-200 text-[#20102d] hover:bg-violet-100">{submitting ? "Creando…" : "Crear sesión"}</Button></section>;
}

function CaptureSessionPanel({ sessions, selectedId, creating, onSelect, onCreate }: { sessions: any[]; selectedId: string | null; creating: boolean; onSelect: (id: string | null) => void; onCreate: () => void }) {
  return <section className="mt-5 border border-violet-200/15 bg-violet-200/[.03] p-5"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-violet-200">Modo sesión de campo</p><h2 className="mt-1 font-display text-2xl text-white">CaptureSession</h2><p className="mt-2 max-w-2xl text-xs leading-5 text-slate-400">Agrupa objetos, evidencias, notas y sincronización de una salida de Mapper. Una sesión no cambia las reglas de verificación ni publica datos por sí sola.</p></div><div className="flex flex-wrap items-center gap-2"><select aria-label="Seleccionar CaptureSession" value={selectedId ?? "ALL"} onChange={event => onSelect(event.target.value === "ALL" ? null : event.target.value)} className="min-w-56 border border-white/10 bg-black/20 px-3 py-2 text-xs text-white"><option value="ALL">Todas las sesiones</option>{sessions.map(session => <option key={session.publicId} value={session.publicId}>{session.name} · {session.objectCount} objetos</option>)}</select><Button disabled={creating} onClick={onCreate} variant="outline" className="border-violet-200/30 text-violet-100"><FolderKanban className="mr-2 h-4 w-4" />Nueva sesión</Button></div></div>{sessions.length ? <div className="mt-4 flex flex-wrap gap-2">{sessions.slice(0, 6).map(session => <button type="button" key={session.publicId} onClick={() => onSelect(selectedId === session.publicId ? null : session.publicId)} className={`border px-3 py-2 text-left text-xs ${selectedId === session.publicId ? "border-violet-200/50 bg-violet-200/10 text-violet-100" : "border-white/10 bg-black/20 text-slate-300"}`}><span className="font-semibold">{session.name}</span><span className="ml-2 text-slate-500">{session.status} · {session.objectCount} obj.</span></button>)}</div> : <p className="mt-4 text-xs text-slate-500">Aún no hay sesiones. Crea una para agrupar la próxima importación o captura manual.</p>}</section>;
}

function CreateObjectForm({ submitting, sessionPublicId, onCancel, onSubmit }: { submitting: boolean; sessionPublicId?: string; onCancel: () => void; onSubmit: (value: { objectType: string; name: string; description: string; latitude: string; longitude: string; accuracyMeters: number; geometry: Record<string, unknown>; captureSessionPublicId?: string }) => void }) {
  const [form, setForm] = useState({ objectType: "PLACE", name: "", description: "", latitude: "", longitude: "", accuracyMeters: "10" });
  const [gpsMessage, setGpsMessage] = useState("GPS pendiente");
  const update = (key: keyof typeof form, value: string) => setForm(current => ({ ...current, [key]: value }));
  const useCurrentLocation = () => {
    if (!navigator.geolocation) { setGpsMessage("Este dispositivo no expone geolocalización."); return; }
    setGpsMessage("Solicitando permiso GPS…");
    navigator.geolocation.getCurrentPosition(
      position => { setForm(current => ({ ...current, latitude: position.coords.latitude.toFixed(7), longitude: position.coords.longitude.toFixed(7), accuracyMeters: String(Math.max(1, Math.round(position.coords.accuracy))) })); setGpsMessage("Ubicación GPS capturada; revisa antes de guardar."); },
      error => setGpsMessage(error.code === error.PERMISSION_DENIED ? "Permiso GPS denegado; puedes introducir coordenadas manualmente." : "No se pudo obtener GPS; puedes introducir coordenadas manualmente."),
      { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 },
    );
  };
  return <section className="mt-7 border border-cyan-200/20 bg-cyan-200/[.04] p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-cyan-200">MiLukita Mapper</p><h2 className="mt-1 font-display text-3xl text-white">Capturar un WorldObject</h2><p className="mt-1 text-xs text-slate-500">{sessionPublicId ? `Se asociará a ${sessionPublicId}` : "Sin CaptureSession seleccionada"}</p></div><Button variant="ghost" onClick={onCancel} className="text-slate-300">Cerrar</Button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><label className="text-xs text-slate-300">Tipo<select value={form.objectType} onChange={event => update("objectType", event.target.value)} className="mt-2 w-full border border-white/10 bg-black/20 px-3 py-2 text-sm text-white">{WORLD_OBJECT_TYPES.map(item => <option key={item} value={item}>{item}</option>)}</select></label><label className="text-xs text-slate-300">Nombre<Input value={form.name} onChange={event => update("name", event.target.value)} placeholder="Ej. Huaca del Sol" className="mt-2" /></label><label className="text-xs text-slate-300 md:col-span-2">Descripción<Textarea value={form.description} onChange={event => update("description", event.target.value)} placeholder="Qué se observó y por qué se registra" className="mt-2" /></label><label className="text-xs text-slate-300">Latitud<Input value={form.latitude} onChange={event => update("latitude", event.target.value)} placeholder="-8.1100" className="mt-2" /></label><label className="text-xs text-slate-300">Longitud<Input value={form.longitude} onChange={event => update("longitude", event.target.value)} placeholder="-79.0200" className="mt-2" /></label><label className="text-xs text-slate-300">Precisión en metros<Input type="number" min="0" value={form.accuracyMeters} onChange={event => update("accuracyMeters", event.target.value)} className="mt-2" /></label></div><div className="mt-4 flex flex-wrap items-center gap-3 border border-cyan-200/15 bg-cyan-200/[.04] p-3"><Button type="button" variant="outline" onClick={useCurrentLocation} className="border-cyan-200/30 text-cyan-100"><MapPin className="mr-2 h-4 w-4" />Usar mi ubicación</Button><span className="text-xs text-slate-400" role="status">{gpsMessage}</span></div><p className="mt-4 text-xs leading-5 text-slate-500"><UploadCloud className="mr-1 inline h-3.5 w-3.5" />La captura inicial registra coordenadas y estructura. La carga binaria se realiza desde el detalle mediante storage controlado; el asset queda restringido hasta una decisión de publicación.</p><Button disabled={submitting || !form.name || !form.description || !form.latitude || !form.longitude} onClick={() => onSubmit({ objectType: form.objectType, name: form.name, description: form.description, latitude: form.latitude, longitude: form.longitude, accuracyMeters: Number(form.accuracyMeters), geometry: { type: "Point", coordinates: [Number(form.longitude), Number(form.latitude)] }, captureSessionPublicId: sessionPublicId })} className="mt-5 bg-cyan-200 text-[#062019] hover:bg-cyan-100">{submitting ? "Capturando…" : "Registrar captura"}</Button></section>;
}

function ObjectDetail({ object, snapshots, restoring, updating, reviewPending, publishPending, onUpdate, onRestore, onReview, onPublish, onAddClaim, onAddSource, onAddEvidence, onUpload }: { object: any; snapshots: Array<{ publicId: string; version: number; snapshotHash: string; createdAt: Date }>; restoring: boolean; updating: boolean; reviewPending: boolean; publishPending: boolean; onUpdate: (value: { objectPublicId: string; objectType: string; name: string; description: string; latitude: string; longitude: string; accuracyMeters: number }) => void; onRestore: (snapshotPublicId: string) => void; onReview: (decision: "REQUEST_EVIDENCE" | "VERIFY" | "DISPUTE" | "REJECT" | "ARCHIVE", reason: string, evidenceReviewed: string[]) => void; onPublish: () => void; onAddClaim: (value: { text: string; claimType: string; observations: string }) => void; onAddSource: (value: { institutionOrPerson: string; sourceType: string; referenceUrl?: string; sourceDate?: Date; authorityLevel: number; observations: string }) => void; onAddEvidence: (value: { evidenceType: string; origin: string; capturedAt: Date; integrityHash: string; metadata?: Record<string, unknown> }) => void; onUpload: (file: File, assetType: string, accessScope: "ADMIN_ONLY" | "REVIEW_ONLY" | "PUBLISHED_RUNTIME") => void }) {
  const [claim, setClaim] = useState({ text: "", claimType: "HISTORICAL", observations: "" });
  const [source, setSource] = useState({ institutionOrPerson: "", sourceType: "INSTITUTIONAL", referenceUrl: "", authorityLevel: "50", observations: "" });
  const [evidence, setEvidence] = useState({ evidenceType: "FIELD_OBSERVATION", origin: "", integrityHash: "", metadata: "" });
  const [reason, setReason] = useState("");
  const [edit, setEdit] = useState({ objectType: object.objectType ?? "PLACE", name: object.name ?? "", description: object.description ?? "", latitude: object.latitude ?? "", longitude: object.longitude ?? "", accuracyMeters: String(object.accuracyMeters ?? 0) });
  const [pendingAsset, setPendingAsset] = useState<{ file: File; url: string; assetType: string; accessScope: "ADMIN_ONLY" | "REVIEW_ONLY" | "PUBLISHED_RUNTIME" } | null>(null);
  useEffect(() => { setEdit({ objectType: object.objectType ?? "PLACE", name: object.name ?? "", description: object.description ?? "", latitude: object.latitude ?? "", longitude: object.longitude ?? "", accuracyMeters: String(object.accuracyMeters ?? 0) }); }, [object.publicId, object.version, object.name, object.description, object.latitude, object.longitude, object.accuracyMeters]);
  const canEdit = !["VERIFIED", "PUBLISHED", "ARCHIVED"].includes(object.status);
  const canVerify = object.status === "UNDER_REVIEW";
  const saveEdit = () => onUpdate({ objectPublicId: object.publicId, objectType: edit.objectType, name: edit.name, description: edit.description, latitude: edit.latitude, longitude: edit.longitude, accuracyMeters: Number(edit.accuracyMeters) });
  const confidenceRows = calculateConfidenceBreakdown({ sourceCount: object.sources.length, evidenceCount: object.evidence.length, claimCount: object.claims.length, accuracyMeters: Number(object.accuracyMeters ?? 0), status: object.status });
  const confidenceScore = confidenceRows.reduce((total, row) => total + row.points, 0);
  return <div><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-mono text-xs text-cyan-200">{object.publicId} · v{object.version}</p><h2 className="mt-2 font-display text-3xl text-white">{object.name}</h2><p className="mt-1 text-sm text-slate-400">{object.objectType} · precisión {object.accuracyMeters} m · {object.latitude}, {object.longitude}</p></div><Badge className={statusTone[object.status] ?? "border-white/15 bg-white/5 text-slate-200"}>{object.status}</Badge></div>
<div className="mt-5 border border-cyan-200/15 bg-cyan-200/[.03] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-cyan-200">Edición previa a confirmación</p><p className="mt-1 text-xs text-slate-400">Los cambios se guardan como nueva versión CAPTURED y deben volver a ser revisados.</p></div><Badge className={canEdit ? "border-cyan-200/30 bg-cyan-200/10 text-cyan-100" : "border-slate-200/20 bg-slate-200/10 text-slate-400"}>{canEdit ? "EDITABLE" : "BLOQUEADO POR WORKFLOW"}</Badge></div><div className="mt-3 grid gap-3 md:grid-cols-2"><label className="text-xs text-slate-300">Tipo<select disabled={!canEdit} value={edit.objectType} onChange={event => setEdit({ ...edit, objectType: event.target.value })} className="mt-2 w-full border border-white/10 bg-black/20 px-3 py-2 text-sm text-white">{WORLD_OBJECT_TYPES.map(item => <option key={item} value={item}>{item}</option>)}</select></label><label className="text-xs text-slate-300">Nombre<Input disabled={!canEdit} value={edit.name} onChange={event => setEdit({ ...edit, name: event.target.value })} className="mt-2" /></label><label className="text-xs text-slate-300 md:col-span-2">Descripción<Textarea disabled={!canEdit} value={edit.description} onChange={event => setEdit({ ...edit, description: event.target.value })} className="mt-2" /></label><label className="text-xs text-slate-300">Latitud<Input disabled={!canEdit} value={edit.latitude} onChange={event => setEdit({ ...edit, latitude: event.target.value })} className="mt-2" /></label><label className="text-xs text-slate-300">Longitud<Input disabled={!canEdit} value={edit.longitude} onChange={event => setEdit({ ...edit, longitude: event.target.value })} className="mt-2" /></label><label className="text-xs text-slate-300">Precisión<Input disabled={!canEdit} type="number" min="0" value={edit.accuracyMeters} onChange={event => setEdit({ ...edit, accuracyMeters: event.target.value })} className="mt-2" /></label></div><Button disabled={!canEdit || updating || !edit.name.trim() || !edit.description.trim()} onClick={saveEdit} className="mt-3 bg-cyan-200 text-[#062019] hover:bg-cyan-100">{updating ? "Guardando versión…" : "Guardar cambios"}</Button></div>
<p className="mt-4 text-sm leading-6 text-slate-300">{object.description}</p><div className="mt-5 border border-amber-200/15 bg-amber-200/[.03] p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-200">The Eye · Evidence Matrix</p><p className="mt-1 text-xs leading-5 text-slate-400">Indicadores de suficiencia y trazabilidad; no representan una probabilidad de verdad.</p></div><Badge className="border border-amber-200/25 bg-amber-200/10 text-amber-100">Confianza explicable · {confidenceScore}/100</Badge></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{confidenceRows.map(row => <div key={row.dimension} className="border border-white/10 bg-black/20 p-3"><div className="flex items-center justify-between gap-2"><span className="text-xs font-semibold text-white">{row.dimension}</span><span className={`text-xs font-bold ${row.points > 0 ? "text-emerald-200" : "text-slate-500"}`}>{row.points} pts</span></div><p className="mt-1 text-xs leading-5 text-slate-400">{row.reason}</p></div>)}</div></div><div className="mt-5 border border-violet-200/15 bg-violet-200/[.03] p-4"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-violet-200">Snapshots históricos</p><p className="mt-1 text-xs text-slate-400">Versiones inmutables; restaurar siempre crea una nueva versión.</p></div><Badge className="border border-violet-200/20 bg-violet-200/10 text-violet-100">{snapshots.length} versiones</Badge></div>{snapshots.length ? <div className="mt-3 space-y-2">{snapshots.map(snapshot => <div key={snapshot.publicId} className="flex flex-wrap items-center justify-between gap-2 border border-white/10 bg-black/20 p-3 text-xs"><span className="text-slate-300">v{snapshot.version} · {new Date(snapshot.createdAt).toLocaleString()} · <span className="font-mono text-slate-500">{snapshot.snapshotHash.slice(0, 12)}…</span></span><Button size="sm" disabled={restoring || snapshot.version === object.version} onClick={() => onRestore(snapshot.publicId)} variant="outline" className="border-violet-200/25 text-violet-100">{snapshot.version === object.version ? "Versión actual" : "Restaurar como nueva"}</Button></div>)}</div> : <p className="mt-3 text-xs text-slate-500">Aún no hay snapshots históricos.</p>}</div><div className="mt-5 grid gap-3 sm:grid-cols-3"><div className="border border-white/10 bg-black/20 p-3"><p className="text-xs text-slate-500">Claims</p><p className="mt-1 text-xl font-bold text-white">{object.claims.length}</p></div><div className="border border-white/10 bg-black/20 p-3"><p className="text-xs text-slate-500">Fuentes</p><p className="mt-1 text-xl font-bold text-white">{object.sources.length}</p></div><div className="border border-white/10 bg-black/20 p-3"><p className="text-xs text-slate-500">Evidencias</p><p className="mt-1 text-xl font-bold text-white">{object.evidence.length}</p></div></div>
<div className="mt-6 border-t border-white/10 pt-5"><p className="text-xs font-bold uppercase tracking-[.14em] text-amber-200">The Eye · revisión</p><div className="mt-3 grid gap-3 md:grid-cols-2"><Textarea value={reason} onChange={event => setReason(event.target.value)} placeholder="Motivo de la decisión y observaciones" className="md:col-span-2" /><div className="flex flex-wrap gap-2"><Button disabled={reviewPending || !reason || object.status !== "CAPTURED"} onClick={() => onReview("REQUEST_EVIDENCE", reason, object.evidence.map((item: { publicId: string }) => item.publicId))} variant="outline" className="border-orange-200/30 text-orange-100">Solicitar evidencia</Button><Button disabled={reviewPending || !reason || !canVerify} onClick={() => onReview("VERIFY", reason, object.evidence.map((item: { publicId: string }) => item.publicId))} className="bg-emerald-200 text-[#062019] hover:bg-emerald-100">Verificar</Button><Button disabled={reviewPending || !reason || !canVerify} onClick={() => onReview("DISPUTE", reason, [])} variant="outline" className="border-rose-200/30 text-rose-100">Marcar disputa</Button></div><div className="flex items-center gap-2"><Button disabled={publishPending || object.status !== "VERIFIED"} onClick={onPublish} className="bg-green-200 text-[#062019] hover:bg-green-100">Publicar versión v{object.version}</Button><span className="text-xs text-slate-500">Requiere estado VERIFIED, fuente y evidencia.</span></div></div></div>
<div className="mt-6 grid gap-5 lg:grid-cols-3"><MiniForm title="Claim" onSubmit={() => { onAddClaim(claim); setClaim({ text: "", claimType: "HISTORICAL", observations: "" }); }}><Input value={claim.text} onChange={event => setClaim({ ...claim, text: event.target.value })} placeholder="Afirmación sobre el objeto" /><Input value={claim.claimType} onChange={event => setClaim({ ...claim, claimType: event.target.value })} placeholder="Tipo de claim" /><Textarea value={claim.observations} onChange={event => setClaim({ ...claim, observations: event.target.value })} placeholder="Observaciones" /></MiniForm><MiniForm title="Source" onSubmit={() => { onAddSource({ ...source, authorityLevel: Number(source.authorityLevel), referenceUrl: source.referenceUrl || undefined }); setSource({ institutionOrPerson: "", sourceType: "INSTITUTIONAL", referenceUrl: "", authorityLevel: "50", observations: "" }); }}><Input value={source.institutionOrPerson} onChange={event => setSource({ ...source, institutionOrPerson: event.target.value })} placeholder="Institución o persona" /><Input value={source.sourceType} onChange={event => setSource({ ...source, sourceType: event.target.value })} placeholder="Tipo de fuente" /><Input value={source.referenceUrl} onChange={event => setSource({ ...source, referenceUrl: event.target.value })} placeholder="https://… (opcional)" /><Input type="number" min="0" max="100" value={source.authorityLevel} onChange={event => setSource({ ...source, authorityLevel: event.target.value })} placeholder="Autoridad 0–100" /></MiniForm><MiniForm title="Evidence" onSubmit={() => { onAddEvidence({ evidenceType: evidence.evidenceType, origin: evidence.origin, capturedAt: new Date(), integrityHash: evidence.integrityHash, metadata: evidence.metadata ? { note: evidence.metadata } : undefined }); setEvidence({ evidenceType: "FIELD_OBSERVATION", origin: "", integrityHash: "", metadata: "" }); }}><Input value={evidence.evidenceType} onChange={event => setEvidence({ ...evidence, evidenceType: event.target.value })} placeholder="PHOTO, VIDEO, DOCUMENT…" /><Input value={evidence.origin} onChange={event => setEvidence({ ...evidence, origin: event.target.value })} placeholder="Origen o referencia" /><Input value={evidence.integrityHash} onChange={event => setEvidence({ ...evidence, integrityHash: event.target.value })} placeholder="SHA-256 u otra huella" /><Textarea value={evidence.metadata} onChange={event => setEvidence({ ...evidence, metadata: event.target.value })} placeholder="Metadatos" /></MiniForm></div>
<div className="mt-6 border-t border-white/10 pt-5"><p className="text-xs font-bold uppercase tracking-[.14em] text-cyan-200">Assets protegidos en S3</p>{object.assetRecords?.length ? <div className="mt-3 space-y-2">{object.assetRecords.map((asset: { publicId: string; originalName: string; mimeType: string; byteSize: number; accessScope: string }) => <div key={asset.publicId} className="flex flex-wrap items-center justify-between gap-2 border border-white/10 bg-black/20 p-3 text-xs"><span className="text-slate-200">{asset.originalName} · {asset.mimeType} · {(asset.byteSize / 1024 / 1024).toFixed(2)} MB</span><Badge className="border-white/15 bg-white/5 text-slate-300">{asset.accessScope}</Badge></div>)}</div> : null}<label className="mt-3 flex cursor-pointer items-center gap-3 border border-dashed border-cyan-200/20 bg-cyan-200/[.03] p-4 text-sm text-slate-300"><Upload className="h-4 w-4 text-cyan-200" /><span>Seleccionar foto, video, PDF o evidencia</span><input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,application/pdf,text/plain" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) setPendingAsset({ file, url: URL.createObjectURL(file), assetType: "FIELD_ASSET", accessScope: "ADMIN_ONLY" }); event.target.value = ""; }} /></label><p className="mt-2 text-xs text-slate-500">Máximo 20 MB. La previsualización es local; el upload solo ocurre al confirmar.</p></div>
<div className="mt-6 border-t border-white/10 pt-5"><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-500">Historial de verificaciones</p>{object.reviews.length ? <div className="mt-3 space-y-2">{object.reviews.map((item: { publicId: string; decision: string; reason: string; approvedVersion: number | null }) => <div key={item.publicId} className="border border-white/10 bg-black/20 p-3 text-xs"><p className="font-bold text-white">{item.decision} {item.approvedVersion ? `· v${item.approvedVersion}` : ""}</p><p className="mt-1 text-slate-400">{item.reason}</p></div>)}</div> : <p className="mt-3 text-sm text-slate-500">Aún no hay decisiones registradas.</p>}</div>
{pendingAsset ? <div className="fixed inset-0 z-50 grid place-items-center bg-black/75 p-4" role="dialog" aria-modal="true" aria-labelledby="asset-preview-title"><div className="w-full max-w-2xl border border-cyan-200/25 bg-[#071a14] p-5 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-cyan-200">Previsualización segura</p><h3 id="asset-preview-title" className="mt-1 font-display text-2xl text-white">Verificar antes de guardar</h3><p className="mt-2 text-xs text-slate-400">{pendingAsset.file.name} · {(pendingAsset.file.size / 1024 / 1024).toFixed(2)} MB · {pendingAsset.file.type || "tipo desconocido"}</p></div><Button variant="ghost" onClick={() => { URL.revokeObjectURL(pendingAsset.url); setPendingAsset(null); }} className="text-slate-300">Cerrar</Button></div><div className="mt-5 grid min-h-[220px] place-items-center bg-black/30 p-3">{pendingAsset.file.type.startsWith("image/") ? <img src={pendingAsset.url} alt="Previsualización de la evidencia seleccionada" className="max-h-[360px] max-w-full object-contain" /> : pendingAsset.file.type.startsWith("video/") ? <video src={pendingAsset.url} controls className="max-h-[360px] max-w-full" /> : <div className="text-center"><FileCheck2 className="mx-auto h-10 w-10 text-cyan-200" /><p className="mt-3 text-sm text-slate-200">Este tipo de archivo no tiene vista previa visual.</p><p className="mt-1 text-xs text-slate-500">Se verificará MIME, tamaño e integridad SHA-256 al subirlo.</p></div>}</div><div className="mt-5 flex flex-wrap justify-end gap-2"><Button variant="outline" onClick={() => { URL.revokeObjectURL(pendingAsset.url); setPendingAsset(null); }} className="border-white/15 text-white">Cancelar</Button><Button onClick={() => { onUpload(pendingAsset.file, pendingAsset.assetType, pendingAsset.accessScope); URL.revokeObjectURL(pendingAsset.url); setPendingAsset(null); }} className="bg-cyan-200 text-[#062019] hover:bg-cyan-100"><Upload className="mr-2 h-4 w-4" />Confirmar subida protegida</Button></div></div></div> : null}</div>;
}

function fileToBase64(file: File): Promise<string> { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(",")[1] ?? ""); reader.onerror = () => reject(new Error("FILE_READ_FAILED")); reader.readAsDataURL(file); }); }

function MiniForm({ title, onSubmit, children }: { title: string; onSubmit: () => void; children: ReactNode }) { return <form onSubmit={event => { event.preventDefault(); onSubmit(); }} className="space-y-2 border border-white/10 bg-black/20 p-3"><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-400">Añadir {title}</p>{children}<Button type="submit" size="sm" variant="outline" className="border-white/15 text-white hover:bg-white/10">Guardar {title}</Button></form>; }

type OperationsPanelProps = { exporting: boolean; importing: boolean; progress: number; importRef: RefObject<HTMLInputElement | null>; sessionPublicId?: string; onExport: (format: "csv" | "geojson") => void; onImport: (format: "csv" | "geojson", content: string, sessionPublicId?: string) => void };
function OperationsPanel({ exporting, importing, progress, importRef, sessionPublicId, onExport, onImport }: OperationsPanelProps) {
  const [format, setFormat] = useState<"csv" | "geojson">("csv");
  const handleFile = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const content = await file.text(); onImport(format, content, sessionPublicId); event.target.value = ""; };
  return <section className="mt-5 border border-white/10 bg-white/[.03] p-5"><div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-slate-400">Gestión masiva</p><h2 className="mt-1 font-display text-2xl text-white">CSV / GeoJSON</h2><p className="mt-2 max-w-2xl text-xs leading-5 text-slate-400">La importación crea capturas en CAPTURED y, si existe una sesión activa, las agrupa en ella. Ningún archivo importado se publica automáticamente.</p></div><div className="flex flex-wrap items-center gap-2"><select aria-label="Formato de importación" value={format} onChange={event => setFormat(event.target.value as "csv" | "geojson")} className="border border-white/10 bg-black/20 px-3 py-2 text-xs text-white"><option value="csv">CSV</option><option value="geojson">GeoJSON</option></select><input ref={importRef} type="file" accept={format === "csv" ? ".csv,text/csv" : ".geojson,application/geo+json,application/json"} onChange={handleFile} className="hidden" /><Button disabled={importing} onClick={() => importRef.current?.click()} variant="outline" className="border-cyan-200/30 text-cyan-100"><Upload className="mr-2 h-4 w-4" />{importing ? "Importando…" : "Importar"}</Button><Button disabled={exporting} onClick={() => onExport(format)} className="bg-cyan-200 text-[#062019] hover:bg-cyan-100"><Download className="mr-2 h-4 w-4" />{exporting ? "Preparando…" : "Exportar"}</Button></div></div>{importing || progress === 100 ? <div className="mt-4" role="status" aria-live="polite"><div className="mb-2 flex justify-between text-xs text-cyan-100"><span>{progress === 100 ? "Importación completada" : "Validando e importando registros…"}</span><span>{progress}%</span></div><div className="h-2 overflow-hidden bg-white/10"><div className="h-full bg-cyan-200 transition-[width] duration-300" style={{ width: `${progress}%` }} /></div></div> : null}</section>;
}

type RolePanelProps = { myRole: string | null | undefined; roles: Array<{ userId: number; role: string; assignedByUserId: number | null; updatedAt: Date }>; assigning: boolean; onAssign: (userId: number, role: MapperRole) => void };
function RolePanel({ myRole, roles, assigning, onAssign }: RolePanelProps) { const [userId, setUserId] = useState(""); const [role, setRole] = useState<MapperRole>("MAPPER_OPERATOR"); return <section className="mt-5 border border-violet-200/15 bg-violet-200/[.04] p-5"><div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-end"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-violet-200">RBAC territorial</p><h2 className="mt-1 font-display text-2xl text-white">Separación de privilegios</h2><p className="mt-2 text-xs leading-5 text-slate-400">Tu rol territorial actual: <strong className="text-violet-100">{myRole ?? "HUMAN_AUTHORITY por rol admin"}</strong>. Mapper captura; The Eye verifica; Human Authority publica.</p></div><div className="flex flex-wrap items-center gap-2"><Input value={userId} onChange={event => setUserId(event.target.value)} inputMode="numeric" placeholder="ID de usuario" className="w-32" /><select aria-label="Rol territorial" value={role} onChange={event => setRole(event.target.value as MapperRole)} className="border border-white/10 bg-black/20 px-3 py-2 text-xs text-white">{MAPPER_ROLES.map(item => <option key={item} value={item}>{item}</option>)}</select><Button disabled={assigning || !userId} onClick={() => onAssign(Number(userId), role)} className="bg-violet-200 text-[#20102d] hover:bg-violet-100"><UserCog className="mr-2 h-4 w-4" />Asignar</Button></div></div>{roles.length ? <div className="mt-4 flex flex-wrap gap-2">{roles.map(item => <Badge key={item.userId} className="border border-white/10 bg-black/20 text-slate-200">Usuario {item.userId}: {item.role}</Badge>)}</div> : <p className="mt-4 text-xs text-slate-500">No hay asignaciones explícitas. Un administrador conserva únicamente el fallback Human Authority hasta asignar un subrol.</p>}</section>; }
